    "apply90.75a28759ca": "কমপক্ষে একটি চিপ ট্যাপ করুন — অথবা অন্য কিছু নাম দিন।",
    "apply90.936d32b433": "চালিয়ে যাওয়ার আগে রেকর্ডিং বন্ধ করুন।",
    "apply90.7651d6a007": "আমাদের একটি জিনিস দিন — কয়েকটি বাক্য, একটি ফাইল, বা একটি ভয়েস নোট।",
    "apply90.a621300e57": "আরও কয়েকটি বাক্য — কমপক্ষে ৪০ অক্ষর।",
    "apply90.989a5bb0e3": "অনুগ্রহ করে আপনার পুরো নাম লিখুন। এখানে পরিচয় নথি পাঠাবেন না।",
    "apply90.6e67bf1cd9": "সেই ইমেলটি সঠিক দেখাচ্ছে না — বানান পরীক্ষা করুন।",
    "apply90.4f97a3c024": "অনুগ্রহ করে আপনার বসবাসের দেশ লিখুন।",
    "apply90.e2ace3c625": "একটি লিঙ্ক, অনুগ্রহ করে — লিঙ্কডইন, গিটহাব, একটি পেপার, প্রেস… যেকোনো জায়গায় আমরা আপনার কাজ দেখতে পারি।",
    "apply90.152ecad115": "সেই লিঙ্কটি ইউআরএল-এর মতো দেখাচ্ছে না — linkedin.com/in/you এর মতো কিছু কাজ করে।",
    "apply.editLabel": "{section} সম্পাদনা করুন (আপনার উত্তরগুলি সংরক্ষিত আছে)",
    "apply.editTitle": "আপনার উত্তর না হারিয়ে সম্পাদনা করুন",
    "apply.yourVoice": "আপনার ভয়েস নোট",
    "apply90.a89491addd": "এটি একটি পূর্বরূপ। এখান থেকে কোনো আবেদন পাঠানো হয় না। আসল আবেদনের জন্য enki.ngo ব্যবহার করুন; আপনার উত্তরগুলি এই পৃষ্ঠায় থাকবে।",
    "apply90.c6c9be6f56": "অঙ্গীকারে টিক দিন — এটি একটি বাক্যে পুরো চুক্তি।",
    "apply90.e11adeb687": "আপনার সংযুক্তিগুলি একসাথে পাঠানোর জন্য খুব বড়। একটি সরিয়ে ফেলুন বা একটি পাবলিক পোর্টফোলিও লিঙ্ক ব্যবহার করুন। আপনার উত্তরগুলি এখনও এখানে আছে।",
    "apply90.b8ed5279e8": "পাঠানো হচ্ছে…",
    "apply90.27497cc31f": "আমরা নিশ্চিত করতে পারিনি যে আপনার আবেদন সংরক্ষিত হয়েছে। আপনার উত্তরগুলি এখনও এখানে আছে। আবার চেষ্টা করুন, অথবা এটি চলতে থাকলে hello@enki.ngo-তে যোগাযোগ করুন।",
